/**
 * Supabase Auth e-mails (supabase/templates, generated by scripts/generate-auth-email-templates.mjs),
 * rendered by the real Auth server of the local stack and read from its test mailbox (Mailpit).
 * Every template is triggered for real: language from the user's metadata (French when
 * absent), Tamurt Jobs identity, link to /auth/confirm with its one-time token, nothing left
 * unrendered. No e-mail leaves the machine.
 */
import { randomUUID } from "node:crypto";
import { describe, expect, it } from "vitest";
import { createClient } from "@supabase/supabase-js";
import { MAILPIT_URL, PUBLISHABLE_KEY, SUPABASE_URL, serviceClient } from "../../helpers/supabase";
import { totp } from "../../helpers/totp";

type Mail = { Subject: string; HTML: string; To: { Address: string }[] };
const PASSWORD = "Str0ngPassw0rd!";
const email = (tag: string) => `auth.mail.${tag}.${randomUUID().slice(0, 8)}@example.test`;
const client = () => createClient(SUPABASE_URL, PUBLISHABLE_KEY, { auth: { persistSession: false, autoRefreshToken: false } });
const pause = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** The messages sent to `to` (newest first), waiting until `count` have arrived. */
async function mails(to: string, count = 1, timeoutMs = 15_000): Promise<Mail[]> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const list = (await (await fetch(`${MAILPIT_URL}/api/v1/search?query=${encodeURIComponent(`to:"${to}"`)}`)).json()) as { messages?: { ID: string }[] };
    if ((list.messages?.length ?? 0) >= count) {
      return Promise.all(list.messages!.map(async (m) => (await (await fetch(`${MAILPIT_URL}/api/v1/message/${m.ID}`)).json()) as Mail));
    }
    await pause(300);
  }
  throw new Error(`no ${count} e-mail(s) for ${to}`);
}

function expectBranded(mail: Mail, lang: "fr" | "en" | "es" | "ar") {
  expect(mail.HTML).toContain(`lang="${lang}"`);
  expect(mail.HTML).toContain(lang === "ar" ? 'dir="rtl"' : 'dir="ltr"');
  expect(mail.HTML).toContain("TAMURT");
  expect(mail.HTML).toContain("#0b1640"); // night-blue band of the identity
  expect(mail.Subject).toMatch(/· Tamurt Jobs$/);
  for (const text of [mail.Subject, mail.HTML]) {
    expect(text).not.toContain("{{");
    expect(text).not.toContain("<no value>");
    expect(text).not.toContain("%!v");
  }
}

/** The confirmation link of the e-mail: our /auth/confirm route with a token and the right type. */
function confirmLink(mail: Mail, type: string, locale: string) {
  const hrefs = [...mail.HTML.matchAll(/href="([^"]+)"/g)].map((m) => m[1].replace(/&amp;/g, "&"));
  const link = hrefs.find((h) => h.includes("/auth/confirm"));
  expect(link, "confirmation link").toBeDefined();
  const url = new URL(link!);
  expect(url.pathname).toBe("/auth/confirm");
  expect(url.searchParams.get("type")).toBe(type);
  expect(url.searchParams.get("locale")).toBe(locale);
  expect(url.searchParams.get("token_hash")).toMatch(/^[A-Za-z0-9_-]{8,}$/);
  // The visible fallback link is the same as the button's.
  expect(hrefs.filter((h) => h === link).length).toBe(2);
  return url;
}

async function confirmedUser(locale: string | null, tag: string) {
  const address = email(tag);
  const { data, error } = await serviceClient.auth.admin.createUser({
    email: address,
    password: PASSWORD,
    email_confirm: true,
    user_metadata: { account_type: "candidate", first_name: "Mail", last_name: "Test", terms_accepted: true, terms_version: "2026-11-01", ...(locale ? { locale } : {}) },
  });
  if (error) throw error;
  const c = client();
  const signIn = await c.auth.signInWithPassword({ email: address, password: PASSWORD });
  if (signIn.error) throw signIn.error;
  return { id: data.user.id, address, client: c };
}

describe("Supabase Auth e-mails: language, identity and links", () => {
  it("sign-up confirmation, in the language chosen at sign-up (English)", async () => {
    const address = email("signup");
    const { error } = await client().auth.signUp({
      email: address,
      password: PASSWORD,
      options: { data: { account_type: "candidate", first_name: "Lina", last_name: "Test", locale: "en", terms_accepted: true, terms_version: "2026-11-01" } },
    });
    expect(error).toBeNull();
    const [mail] = await mails(address);
    expect(mail.Subject).toBe("Confirm your e-mail address · Tamurt Jobs");
    expectBranded(mail, "en");
    confirmLink(mail, "email", "en");
    expect(mail.HTML).toContain("This link is valid for 1 hour and works only once.");
  });

  it("password reset, in French by default when the account has no language", async () => {
    const user = await confirmedUser(null, "recovery");
    await client().auth.resetPasswordForEmail(user.address);
    const [mail] = await mails(user.address);
    expect(mail.Subject).toBe("Réinitialisez votre mot de passe · Tamurt Jobs");
    expectBranded(mail, "fr");
    confirmLink(mail, "recovery", "fr");
  });

  it("e-mail change: both addresses are asked to confirm (Spanish), then the old one is told", async () => {
    const user = await confirmedUser("es", "change");
    const next = email("changed");
    const { error } = await user.client.auth.updateUser({ email: next });
    expect(error).toBeNull();
    const [toOld] = await mails(user.address);
    const [toNew] = await mails(next);
    for (const mail of [toOld, toNew]) {
      expect(mail.Subject).toBe("Confirme su nueva dirección de correo · Tamurt Jobs");
      expectBranded(mail, "es");
      expect(mail.HTML).toContain(user.address);
      expect(mail.HTML).toContain(next);
    }
    // Confirming from both addresses completes the change; the security notice follows.
    for (const mail of [toOld, toNew]) {
      const url = confirmLink(mail, "email_change", "es");
      const verified = await user.client.auth.verifyOtp({ type: "email_change", token_hash: url.searchParams.get("token_hash")! });
      expect(verified.error).toBeNull();
    }
    const notices = (await mails(user.address, 2)).filter((m) => m.Subject.startsWith("La dirección de correo de su cuenta"));
    expect(notices).toHaveLength(1);
    expectBranded(notices[0], "es");
  });

  it("sign-in link (Arabic, right to left) and invitation (English)", async () => {
    const user = await confirmedUser("ar", "magic");
    await pause(1100);
    const otp = await client().auth.signInWithOtp({ email: user.address, options: { shouldCreateUser: false } });
    expect(otp.error).toBeNull();
    const magic = (await mails(user.address)).find((m) => m.Subject.includes("رابط تسجيل الدخول"));
    expect(magic).toBeDefined();
    expectBranded(magic!, "ar");
    confirmLink(magic!, "magiclink", "ar");

    const invited = email("invite");
    const invite = await serviceClient.auth.admin.inviteUserByEmail(invited, { data: { locale: "en" } });
    expect(invite.error).toBeNull();
    const [mail] = await mails(invited);
    expect(mail.Subject).toBe("Your invitation to Tamurt Jobs · Tamurt Jobs");
    expectBranded(mail, "en");
    confirmLink(mail, "invite", "en");
  });

  it("re-authentication code, then the « password changed » security notice", async () => {
    const user = await confirmedUser("fr", "reauth");
    const reauth = await user.client.auth.reauthenticate();
    expect(reauth.error).toBeNull();
    const [codeMail] = await mails(user.address);
    const code = codeMail.Subject.match(/(\d{6})/)?.[1];
    expect(code, "code in the subject").toBeDefined();
    expect(codeMail.Subject).toBe(`Votre code de vérification : ${code} · Tamurt Jobs`);
    expect(codeMail.HTML).toContain(`>${code}</span>`);
    expectBranded(codeMail, "fr");

    const changed = await user.client.auth.updateUser({ password: "Un-Autre-Mot-De-Passe-2", nonce: code });
    expect(changed.error).toBeNull();
    const notice = (await mails(user.address, 2)).find((m) => m.Subject === "Votre mot de passe a été modifié · Tamurt Jobs");
    expect(notice).toBeDefined();
    expectBranded(notice!, "fr");
    expect(notice!.HTML).toContain("/fr/forgot-password");
  });

  it("security notices when an authenticator app is added, then removed", async () => {
    const user = await confirmedUser("en", "mfa");
    const enrolled = await user.client.auth.mfa.enroll({ factorType: "totp", friendlyName: `test-${randomUUID().slice(0, 6)}` });
    expect(enrolled.error).toBeNull();
    const factorId = enrolled.data!.id;
    const challenge = await user.client.auth.mfa.challenge({ factorId });
    const verify = await user.client.auth.mfa.verify({ factorId, challengeId: challenge.data!.id, code: totp(enrolled.data!.totp!.secret) });
    expect(verify.error).toBeNull();
    const added = (await mails(user.address)).find((m) => m.Subject === "A verification method was added to your account · Tamurt Jobs");
    expect(added).toBeDefined();
    expectBranded(added!, "en");

    const removed = await user.client.auth.mfa.unenroll({ factorId });
    expect(removed.error).toBeNull();
    const notice = (await mails(user.address, 2)).find((m) => m.Subject === "A verification method was removed from your account · Tamurt Jobs");
    expect(notice).toBeDefined();
    expectBranded(notice!, "en");
  });
});
